"use client"

import AlertDialog, {
  useImperativeAlertDialog,
} from "@/components/ui/astryx-alert-dialog"

export default function AlertDialogDemo() {
  const alert = useImperativeAlertDialog()

  const alertProps = {
    title: "Delete item?",
    description:
      "This action cannot be undone. The item and all its data will be permanently removed.",
    actionLabel: "Delete",
  } as const

  return (
    <div
      data-astryx-theme="neutral"
      data-theme="light"
      style={{ colorScheme: "light", display: "contents" }}
    >
      <AlertDialog
        isOpen
        isInline
        onOpenChange={() => {}}
        {...alertProps}
        onAction={() =>
          alert.show({ ...alertProps, onAction: () => alert.hide() })
        }
      />
      {alert.element}
    </div>
  )
}
